-- Additive namespace: existing GreenWork and ewu_* tables are intentionally untouched.
CREATE TABLE ewu2_schema_version (version INTEGER PRIMARY KEY, applied_at TEXT NOT NULL);
CREATE TABLE ewu2_actors (id TEXT PRIMARY KEY, role TEXT NOT NULL CHECK(role IN ('owner','recruiter','finance','partner')), partner_id TEXT);
CREATE TABLE ewu2_settings (key TEXT PRIMARY KEY, value TEXT NOT NULL);
INSERT INTO ewu2_settings VALUES ('ai_enabled','false');
CREATE TABLE ewu2_candidates (id TEXT PRIMARY KEY, telegram_id TEXT NOT NULL UNIQUE, language TEXT NOT NULL, profile TEXT NOT NULL, restricted INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, recruiter_id TEXT, status TEXT NOT NULL DEFAULT 'PROFILE_IN_PROGRESS');
CREATE TABLE ewu2_contacts (id TEXT PRIMARY KEY, candidate_id TEXT NOT NULL REFERENCES ewu2_candidates(id), kind TEXT NOT NULL, value TEXT NOT NULL, UNIQUE(candidate_id,kind));
CREATE TABLE ewu2_partners (id TEXT PRIMARY KEY, name TEXT NOT NULL, contact TEXT NOT NULL);
CREATE TABLE ewu2_vacancies (id TEXT PRIMARY KEY, partner_id TEXT NOT NULL REFERENCES ewu2_partners(id), external_id TEXT NOT NULL, data TEXT NOT NULL, status TEXT NOT NULL, confirmed_at TEXT NOT NULL, expires_at TEXT NOT NULL, UNIQUE(partner_id,external_id));
CREATE TABLE ewu2_applications (id TEXT PRIMARY KEY, candidate_id TEXT NOT NULL REFERENCES ewu2_candidates(id), vacancy_id TEXT NOT NULL REFERENCES ewu2_vacancies(id), partner_id TEXT NOT NULL REFERENCES ewu2_partners(id), status TEXT NOT NULL, instructions TEXT NOT NULL DEFAULT '{}', created_at TEXT NOT NULL, updated_at TEXT NOT NULL, UNIQUE(candidate_id,vacancy_id));
CREATE TABLE ewu2_privacy_records (id TEXT PRIMARY KEY, user_id TEXT NOT NULL, version TEXT NOT NULL, revision TEXT NOT NULL, language TEXT NOT NULL, event TEXT NOT NULL, decision TEXT NOT NULL, source TEXT NOT NULL, notice TEXT NOT NULL, at TEXT NOT NULL, previous_hash TEXT NOT NULL, event_hash TEXT NOT NULL UNIQUE);
CREATE INDEX ewu2_privacy_user ON ewu2_privacy_records(user_id,at);
CREATE TABLE ewu2_privacy_state (user_id TEXT PRIMARY KEY, revision TEXT NOT NULL, allowed INTEGER NOT NULL, language TEXT NOT NULL);
CREATE TABLE ewu2_consents (user_id TEXT NOT NULL, purpose TEXT NOT NULL, granted INTEGER NOT NULL, version TEXT NOT NULL, at TEXT NOT NULL, PRIMARY KEY(user_id,purpose));
CREATE TABLE ewu2_rights_requests (id TEXT PRIMARY KEY, user_id TEXT NOT NULL, kind TEXT NOT NULL, status TEXT NOT NULL, created_at TEXT NOT NULL, UNIQUE(user_id,kind,status));
CREATE TABLE ewu2_recruitment_events (id TEXT PRIMARY KEY, application_id TEXT NOT NULL REFERENCES ewu2_applications(id), from_status TEXT NOT NULL, to_status TEXT NOT NULL, actor_id TEXT NOT NULL, at TEXT NOT NULL);
CREATE TABLE ewu2_followups (id TEXT PRIMARY KEY, application_id TEXT REFERENCES ewu2_applications(id), due_at TEXT NOT NULL, attempts INTEGER NOT NULL DEFAULT 0, max_attempts INTEGER NOT NULL, interval_hours INTEGER NOT NULL, status TEXT NOT NULL, candidate_id TEXT REFERENCES ewu2_candidates(id), template TEXT NOT NULL DEFAULT 'follow_up');
CREATE TABLE ewu2_arrivals (application_id TEXT PRIMARY KEY REFERENCES ewu2_applications(id), reported_at TEXT NOT NULL, confirmed_at TEXT, confirmed_by TEXT);
CREATE TABLE ewu2_employment_starts (application_id TEXT PRIMARY KEY REFERENCES ewu2_applications(id), confirmed_at TEXT NOT NULL, confirmed_by TEXT NOT NULL);
CREATE TABLE ewu2_commissions (id TEXT PRIMARY KEY, application_id TEXT NOT NULL UNIQUE REFERENCES ewu2_applications(id), partner_id TEXT NOT NULL, candidate_id TEXT NOT NULL, model TEXT NOT NULL, rate_minor BIGINT NOT NULL, units INTEGER NOT NULL, currency TEXT NOT NULL, amount_minor BIGINT NOT NULL, contract_ref TEXT NOT NULL, period TEXT NOT NULL, verification TEXT NOT NULL, invoice_date TEXT, due_date TEXT, payment_status TEXT NOT NULL DEFAULT 'UNPAID');
CREATE TABLE ewu2_quality_reports (id TEXT PRIMARY KEY, application_id TEXT NOT NULL REFERENCES ewu2_applications(id), report TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE ewu2_audit_head (singleton INTEGER PRIMARY KEY CHECK(singleton=1), value TEXT NOT NULL);
INSERT INTO ewu2_audit_head VALUES (1,'');
CREATE TABLE ewu2_audit_events (id TEXT PRIMARY KEY, kind TEXT NOT NULL, actor_id TEXT NOT NULL, entity_id TEXT NOT NULL, at TEXT NOT NULL, previous_hash TEXT NOT NULL, event_hash TEXT NOT NULL UNIQUE);
CREATE TABLE ewu2_outbox (id TEXT PRIMARY KEY, topic TEXT NOT NULL, entity_id TEXT NOT NULL, dedupe_key TEXT NOT NULL UNIQUE, payload TEXT NOT NULL, attempts INTEGER NOT NULL DEFAULT 0, status TEXT NOT NULL DEFAULT 'pending', available_at TEXT NOT NULL, lease_until TEXT, last_error TEXT);
CREATE INDEX ewu2_outbox_due ON ewu2_outbox(status,available_at);
CREATE TABLE ewu2_processed_updates (update_id TEXT PRIMARY KEY, processed_at TEXT NOT NULL);
CREATE TABLE ewu2_sessions (user_id TEXT PRIMARY KEY, data TEXT NOT NULL);
CREATE TABLE ewu2_ai_usage (request_id TEXT PRIMARY KEY, reserved_minor BIGINT NOT NULL, spent_minor BIGINT NOT NULL, status TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE INDEX ewu2_apps_partner ON ewu2_applications(partner_id,status);
CREATE INDEX ewu2_apps_candidate ON ewu2_applications(candidate_id);
CREATE INDEX ewu2_followup_due ON ewu2_followups(status,due_at);
CREATE INDEX ewu2_vacancy_live ON ewu2_vacancies(status,expires_at);
CREATE TABLE ewu2_notification_preferences (user_id TEXT PRIMARY KEY, allowed INTEGER NOT NULL);
CREATE TABLE ewu2_deliveries (dedupe_key TEXT PRIMARY KEY, status TEXT NOT NULL, attempted_at TEXT NOT NULL, completed_at TEXT);

CREATE UNIQUE INDEX ewu2_one_app_followup ON ewu2_followups(application_id) WHERE status='pending';
CREATE UNIQUE INDEX ewu2_one_profile_followup ON ewu2_followups(candidate_id) WHERE status='pending' AND application_id IS NULL;
